// Unmounts what a test mounted, from a hook it registers as it loads.
const mounted = new Set()
exports.mount = (view) => {
  mounted.add(view)
  return view
}
afterEach(() => {
  for (const view of mounted) view.unmount()
  mounted.clear()
})

