// A view that listens on the window and is destroyed on a later tick once unmounted.
exports.createView = () => {
  const onDrag = () => {}
  window.addEventListener('dragstart', onDrag)
  return {
    unmount() {
      setTimeout(() => {
        window.removeEventListener('dragstart', onDrag)
      }, 50)
    },
  }
}
